/* SPDX-License-Identifier: MIT */
#include "transport/ca.h"

#include <ctype.h>
#include <dirent.h>
#include <stdatomic.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <curl/curl.h>
#include <curl/curlver.h>
#include <curl/typecheck-gcc.h>

#include "util.h"

/* The well-known locations curl's configure, Go, and rust-native-certs also probe, minus
 * historic-only paths. */
static const char *const BUNDLE_PATHS[] = {
    "/etc/ssl/certs/ca-certificates.crt",                /* Debian, Ubuntu, Arch, Alpine, Gentoo */
    "/etc/pki/tls/certs/ca-bundle.crt",                  /* Fedora, RHEL */
    "/etc/ssl/ca-bundle.pem",                            /* openSUSE */
    "/etc/pki/ca-trust/extracted/pem/tls-ca-bundle.pem", /* RHEL 7+ consolidated trust store */
    "/usr/local/share/certs/ca-root-nss.crt",            /* FreeBSD */
    "/etc/ssl/cert.pem",                                 /* Alpine, FreeBSD, macOS */
};

static const char *const CERT_DIRS[] = {
    "/etc/ssl/certs",     /* Debian and derivatives */
    "/etc/pki/tls/certs", /* Fedora, RHEL */
};

static char *store_file;
static char *store_dir;
/* The probed system store for HTTPS-proxy verification; equals the origin store unless an
 * environment override claimed the origin. */
static char *proxy_file;
static char *proxy_dir;
static int store_missing;

static char *probe_file(const char *root, const char *path)
{
    if (!path)
        return NULL;

    char *full = xasprintf("%s%s", root, path);
    if (access(full, R_OK) != 0) {
        free(full);
        return NULL;
    }
    return full;
}

static int hashed_cert_name(const char *name)
{
    for (int i = 0; i < 8; i++)
        if (!isxdigit((unsigned char)name[i]))
            return 0;
    return strcmp(name + 8, ".0") == 0;
}

enum capath_rule {
    CAPATH_NONE, /* the backend ignores CURLOPT_CAPATH */
    CAPATH_HASHED,
    CAPATH_PLAIN,
};

/* A usable CAPATH is never empty; whether its entries must be hashed depends on the backend. */
static char *probe_dir(const char *root, const char *path, enum capath_rule rule)
{
    if (rule == CAPATH_NONE)
        return NULL;

    char *full = probe_file(root, path);
    if (!full)
        return NULL;

    DIR *dir = opendir(full);
    if (!dir) {
        free(full);
        return NULL;
    }
    int found = 0;
    for (struct dirent *entry; !found && (entry = readdir(dir));) {
        if (entry->d_name[0] == '.')
            continue;
        found = rule == CAPATH_PLAIN || hashed_cert_name(entry->d_name);
    }
    closedir(dir);

    if (!found) {
        free(full);
        return NULL;
    }
    return full;
}

/* A MultiSSL string wraps inactive backends in parentheses; only the active one decides. */
static const char *active_backend(const char *ssl_version)
{
    const char *token = ssl_version;

    while (token && *token) {
        if (*token == ' ') {
            token++;
        } else if (*token == '(') {
            token = strchr(token, ')');
            token = token ? token + 1 : NULL;
        } else {
            return token;
        }
    }
    return NULL;
}

static int backend_is(const char *backend, const char *name)
{
    return backend && strncmp(backend, name, strlen(name)) == 0;
}

/* Pointing an OS-trust backend at a bundle file replaces Keychain / Windows trust instead of
 * restoring it. The AppleSecTrust / NativeCA features (curl >= 8.17) apply to any TLS library. */
static int native_trust(const char *ssl_version, const char *const *features)
{
    for (; features && *features; features++)
        if (strcmp(*features, "AppleSecTrust") == 0 || strcmp(*features, "NativeCA") == 0)
            return 1;

    const char *backend = active_backend(ssl_version);
    return backend_is(backend, "SecureTransport") || backend_is(backend, "Schannel");
}

/* Per SSLSUPP_CA_PATH: OpenSSL and its forks require the hashed layout, GnuTLS / mbedTLS /
 * wolfSSL load plain certificate files, and every other backend ignores the option. */
static enum capath_rule backend_capath_rule(const char *ssl_version)
{
    const char *backend = active_backend(ssl_version);

    if (backend_is(backend, "OpenSSL") || backend_is(backend, "LibreSSL") ||
        backend_is(backend, "BoringSSL") || backend_is(backend, "quictls") ||
        backend_is(backend, "AWS-LC"))
        return CAPATH_HASHED;
    if (backend_is(backend, "GnuTLS") || backend_is(backend, "mbedTLS") ||
        backend_is(backend, "wolfSSL"))
        return CAPATH_PLAIN;
    return CAPATH_NONE;
}

enum ca_store_source ca_resolve(const char *root, const char *env_bundle, const char *env_file,
                                const char *env_dir, const char *ssl_version,
                                const char *const *features, const char *curl_file,
                                const char *curl_dir, char **file, char **dir)
{
    *file = NULL;
    *dir = NULL;

    /* A bundle is a complete trust statement: curl also ignores both SSL_CERT variables when
     * CURL_CA_BUNDLE is set. */
    if (env_bundle && *env_bundle) {
        *file = xstrdup(env_bundle);
        return CA_STORE_ENV;
    }
    if (env_file && *env_file)
        *file = xstrdup(env_file);
    if (env_dir && *env_dir)
        *dir = xstrdup(env_dir);
    if (*file || *dir)
        return CA_STORE_ENV;

    if (native_trust(ssl_version, features))
        return CA_STORE_DEFAULT;
    enum capath_rule rule = backend_capath_rule(ssl_version);
    char *found = probe_file(root, curl_file);
    if (!found)
        found = probe_dir(root, curl_dir, rule);
    if (found) {
        free(found);
        return CA_STORE_DEFAULT;
    }

    for (size_t i = 0; !*file && i < sizeof(BUNDLE_PATHS) / sizeof(BUNDLE_PATHS[0]); i++)
        *file = probe_file(root, BUNDLE_PATHS[i]);
    for (size_t i = 0; !*dir && i < sizeof(CERT_DIRS) / sizeof(CERT_DIRS[0]); i++)
        *dir = probe_dir(root, CERT_DIRS[i], rule);
    return *file || *dir ? CA_STORE_PROBED : CA_STORE_MISSING;
}

static void warn_capath_ignored(void)
{
    static atomic_int warned;

    if (atomic_exchange(&warned, 1))
        return;
    hax_warn("SSL_CERT_DIR is ignored: this libcurl's TLS backend does not support"
             " CA directories");
}

void ca_init(void)
{
/* cainfo/capath joined curl_version_info_data in 7.70.0 (CURLVERSION_SEVENTH). */
#if CURL_AT_LEAST_VERSION(7, 70, 0)
    curl_version_info_data *info = curl_version_info(CURLVERSION_NOW);

    /* Runtimes too old to report their store are distribution builds whose defaults match the
     * system; leave them alone. */
    if (info->age < CURLVERSION_SEVENTH)
        return;
    const char *const *features = NULL;
#if CURL_AT_LEAST_VERSION(7, 87, 0)
    if (info->age >= CURLVERSION_ELEVENTH)
        features = info->feature_names;
#endif
    enum ca_store_source source = ca_resolve("", getenv("CURL_CA_BUNDLE"), getenv("SSL_CERT_FILE"),
                                             getenv("SSL_CERT_DIR"), info->ssl_version, features,
                                             info->cainfo, info->capath, &store_file, &store_dir);
    store_missing = source == CA_STORE_MISSING;
    if (source == CA_STORE_PROBED) {
        proxy_file = store_file ? xstrdup(store_file) : NULL;
        proxy_dir = store_dir ? xstrdup(store_dir) : NULL;
    } else if (source == CA_STORE_ENV) {
        /* Environment overrides claim only the origin, so proxies still need the system store
         * discovered when libcurl's default is invalid. */
        ca_resolve("", NULL, NULL, NULL, info->ssl_version, features, info->cainfo, info->capath,
                   &proxy_file, &proxy_dir);
    }
#endif
}

void ca_apply(CURL *curl)
{
    if (store_file)
        curl_easy_setopt(curl, CURLOPT_CAINFO, store_file);
    if (store_dir) {
        /* Only an environment SSL_CERT_DIR can be unsupported here; probing already skips
         * backends without CAPATH support. */
        CURLcode result = curl_easy_setopt(curl, CURLOPT_CAPATH, store_dir);
        if (result == CURLE_NOT_BUILT_IN || result == CURLE_UNKNOWN_OPTION)
            warn_capath_ignored();
    }

    /* HTTPS proxies (https_proxy in the environment) verify with their own options, always
     * against the system store: environment overrides follow curl's origin-only semantics. */
    if (proxy_file)
        curl_easy_setopt(curl, CURLOPT_PROXY_CAINFO, proxy_file);
    if (proxy_dir)
        curl_easy_setopt(curl, CURLOPT_PROXY_CAPATH, proxy_dir);
}

const char *ca_verify_hint(CURLcode code)
{
    if (!store_missing)
        return NULL;
    if (code != CURLE_PEER_FAILED_VERIFICATION && code != CURLE_SSL_CACERT_BADFILE)
        return NULL;
    return "no CA certificate store found on this system; "
           "install the ca-certificates package or set SSL_CERT_FILE";
}

void ca_warn_verify_failure(CURLcode code)
{
    static atomic_int warned;
    const char *hint = ca_verify_hint(code);

    if (!hint || atomic_exchange(&warned, 1))
        return;
    hax_warn("%s", hint);
}

/* SPDX-License-Identifier: MIT */
#include "transport/http.h"

#include <ctype.h>
#include <limits.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <time.h>
#include <curl/curl.h>
#include <curl/easy.h>
#include <curl/system.h>
#include <curl/typecheck-gcc.h>

#include "trace.h"
#include "util.h"
#include "version.h"
#include "transport/ca.h"
#include "transport/sse.h"

#define ERROR_BODY_MAX_BYTES 4096
/* Default identity; a User-Agent entry in the caller's headers overrides it. */
#define HTTP_USER_AGENT "hax/" HAX_VERSION
/* Bound server-requested waits so an interactive request remains responsive. */
#define RETRY_AFTER_MAX_MS (2L * 60L * 1000L)

struct transfer_tick {
    http_tick_cb callback;
    void *user;
    int cancelled;
};

struct sse_request_state {
    struct sse_parser parser;
    struct buf error_body;
    struct transfer_tick tick;
    CURL *curl; /* borrowed; needed to classify body bytes by response status */
    long retry_after_ms;
};

struct buffered_request_state {
    struct buf body;
    long max_bytes;
    struct transfer_tick tick;
};

struct traced_sse_callback {
    sse_cb callback;
    void *user;
};

static char *curl_error_body(CURLcode result)
{
    const char *hint = ca_verify_hint(result);

    if (hint)
        return xasprintf("libcurl: %s (%s)", curl_easy_strerror(result), hint);
    return xasprintf("libcurl: %s", curl_easy_strerror(result));
}

static int poll_transfer(struct transfer_tick *tick)
{
    if (!tick->callback || !tick->callback(tick->user))
        return 0;

    tick->cancelled = 1;
    return 1;
}

static int trace_sse_callback(const char *event_name, const char *data, void *user)
{
    struct traced_sse_callback *traced = user;

    trace_sse_event(event_name, data);
    return traced->callback(event_name, data, traced->user);
}

static int build_header_list(const char *const *headers, const char *extra_header,
                             struct curl_slist **list_out)
{
    struct curl_slist *list = NULL;

    for (const char *const *header = headers; header && *header; header++) {
        struct curl_slist *next = curl_slist_append(list, *header);
        if (!next)
            goto error;
        list = next;
    }
    if (extra_header) {
        struct curl_slist *next = curl_slist_append(list, extra_header);
        if (!next)
            goto error;
        list = next;
    }

    *list_out = list;
    return 0;

error:
    curl_slist_free_all(list);
    *list_out = NULL;
    return -1;
}

static const char **copy_headers_with(const char *const *headers, const char *extra_header)
{
    size_t count = 0;

    for (const char *const *header = headers; header && *header; header++)
        count++;

    const char **copy = xmalloc((count + 2) * sizeof(*copy));
    for (size_t i = 0; i < count; i++)
        copy[i] = headers[i];
    copy[count] = extra_header;
    copy[count + 1] = NULL;
    return copy;
}

static long parse_retry_after_ms(const char *value, size_t len)
{
    while (len > 0 && isspace((unsigned char)*value)) {
        value++;
        len--;
    }
    while (len > 0 && isspace((unsigned char)value[len - 1]))
        len--;
    if (len == 0)
        return 0;

    int all_digits = 1;
    for (size_t i = 0; i < len; i++) {
        if (!isdigit((unsigned char)value[i])) {
            all_digits = 0;
            break;
        }
    }
    if (all_digits) {
        long seconds = 0;
        for (size_t i = 0; i < len; i++) {
            int digit = value[i] - '0';
            if (seconds > (LONG_MAX - digit) / 10)
                return RETRY_AFTER_MAX_MS;
            seconds = seconds * 10 + digit;
        }
        if (seconds > RETRY_AFTER_MAX_MS / 1000)
            return RETRY_AFTER_MAX_MS;
        return seconds * 1000;
    }

    char *date = xmalloc(len + 1);
    memcpy(date, value, len);
    date[len] = '\0';
    time_t retry_at = curl_getdate(date, NULL);
    free(date);
    if (retry_at == (time_t)-1)
        return 0;

    time_t now = time(NULL);
    if (retry_at <= now)
        return 0;
    if ((long)(retry_at - now) > RETRY_AFTER_MAX_MS / 1000)
        return RETRY_AFTER_MAX_MS;
    return (long)(retry_at - now) * 1000;
}

static size_t capture_sse_header(char *data, size_t size, size_t count, void *user)
{
    static const char retry_after[] = "Retry-After:";
    struct sse_request_state *state = user;
    size_t len = size * count;

    if (len >= sizeof(retry_after) - 1 &&
        strncasecmp(data, retry_after, sizeof(retry_after) - 1) == 0) {
        long delay_ms =
            parse_retry_after_ms(data + sizeof(retry_after) - 1, len - (sizeof(retry_after) - 1));
        if (delay_ms > 0)
            state->retry_after_ms = delay_ms;
    }
    return len;
}

static size_t receive_sse_data(char *data, size_t size, size_t count, void *user)
{
    struct sse_request_state *state = user;
    size_t len = size * count;

    /* A short write aborts before a partial event reaches the parser. */
    if (poll_transfer(&state->tick))
        return 0;

    if (state->error_body.len < ERROR_BODY_MAX_BYTES) {
        size_t available = ERROR_BODY_MAX_BYTES - state->error_body.len;
        buf_append(&state->error_body, data, len < available ? len : available);
    }

    /* Error responses can contain valid SSE framing. Delivering those events would mutate the
     * caller's stream state before its retry policy classifies the response. */
    long status = 0;
    curl_easy_getinfo(state->curl, CURLINFO_RESPONSE_CODE, &status);
    if (status == 0 || (status >= 200 && status < 300))
        sse_parser_feed(&state->parser, data, len);
    return len;
}

static int poll_sse_transfer(void *user, curl_off_t download_total, curl_off_t downloaded,
                             curl_off_t upload_total, curl_off_t uploaded)
{
    (void)download_total;
    (void)downloaded;
    (void)upload_total;
    (void)uploaded;
    struct sse_request_state *state = user;
    return poll_transfer(&state->tick);
}

int http_sse_post(const char *url, const char *const *headers, const char *body, size_t body_len,
                  long idle_timeout_s, sse_cb callback, void *user, http_tick_cb tick,
                  void *tick_user, struct http_response *response)
{
    memset(response, 0, sizeof(*response));

    CURL *curl = curl_easy_init();
    if (!curl) {
        response->error_body = xstrdup("curl_easy_init failed");
        return -1;
    }

    struct curl_slist *header_list = NULL;
    if (build_header_list(headers, NULL, &header_list) != 0) {
        curl_easy_cleanup(curl);
        response->error_body = xstrdup("curl_slist_append failed");
        return -1;
    }

    struct sse_request_state state = {
        .tick = {.callback = tick, .user = tick_user},
        .curl = curl,
    };
    struct traced_sse_callback traced = {.callback = callback, .user = user};
    if (trace_enabled())
        sse_parser_init(&state.parser, trace_sse_callback, &traced);
    else
        sse_parser_init(&state.parser, callback, user);

    ca_apply(curl);

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);
    curl_easy_setopt(curl, CURLOPT_USERAGENT, HTTP_USER_AGENT);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, body);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)body_len);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, header_list);
    curl_easy_setopt(curl, CURLOPT_HEADERFUNCTION, capture_sse_header);
    curl_easy_setopt(curl, CURLOPT_HEADERDATA, &state);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, receive_sse_data);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &state);
    if (tick) {
        curl_easy_setopt(curl, CURLOPT_NOPROGRESS, 0L);
        curl_easy_setopt(curl, CURLOPT_XFERINFOFUNCTION, poll_sse_transfer);
        curl_easy_setopt(curl, CURLOPT_XFERINFODATA, &state);
    } else {
        curl_easy_setopt(curl, CURLOPT_NOPROGRESS, 1L);
    }
    curl_easy_setopt(curl, CURLOPT_TCP_KEEPALIVE, 1L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 10L);
    /* A total timeout would reject healthy long streams. The low-speed timeout detects dead
     * connections while allowing local servers to stay quiet during prompt evaluation. */
    if (idle_timeout_s > 0) {
        curl_easy_setopt(curl, CURLOPT_LOW_SPEED_LIMIT, 1L);
        curl_easy_setopt(curl, CURLOPT_LOW_SPEED_TIME, idle_timeout_s);
    }

    trace_request("POST", url, headers, body, body_len);
    CURLcode result = curl_easy_perform(curl);

    long status = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &status);
    if (!state.tick.cancelled)
        sse_parser_finalize(&state.parser);

    curl_slist_free_all(header_list);
    curl_easy_cleanup(curl);

    response->status = status;
    response->retry_after_ms = state.retry_after_ms;
    if (state.tick.cancelled) {
        response->cancelled = 1;
    } else if (result != CURLE_OK) {
        response->error_body = curl_error_body(result);
    } else if (status < 200 || status >= 300) {
        response->error_body =
            state.error_body.data ? buf_steal(&state.error_body) : xstrdup("(no response body)");
    }

    trace_response_status(status, response->error_body);
    sse_parser_free(&state.parser);
    buf_free(&state.error_body);
    return result == CURLE_OK ? 0 : -1;
}

static size_t receive_buffered_data(char *data, size_t size, size_t count, void *user)
{
    struct buffered_request_state *state = user;
    size_t len = size * count;

    if (poll_transfer(&state->tick))
        return 0;
    if (state->max_bytes > 0 && (state->body.len > (size_t)state->max_bytes ||
                                 len > (size_t)state->max_bytes - state->body.len))
        return 0;

    buf_append(&state->body, data, len);
    return len;
}

static int poll_buffered_transfer(void *user, curl_off_t download_total, curl_off_t downloaded,
                                  curl_off_t upload_total, curl_off_t uploaded)
{
    (void)download_total;
    (void)downloaded;
    (void)upload_total;
    (void)uploaded;
    struct buffered_request_state *state = user;
    return poll_transfer(&state->tick);
}

static int buffered_request(const char *url, const char *const *headers, const char *body,
                            size_t body_len, long timeout_s, long max_bytes, http_tick_cb tick,
                            void *tick_user, char **out, long *status_out)
{
    *out = NULL;
    if (status_out)
        *status_out = 0;

    CURL *curl = curl_easy_init();
    if (!curl)
        return -1;

    const char *content_type = body ? "Content-Type: application/json" : NULL;
    struct curl_slist *header_list = NULL;
    if (build_header_list(headers, content_type, &header_list) != 0) {
        curl_easy_cleanup(curl);
        return -1;
    }

    struct buffered_request_state state = {
        .max_bytes = max_bytes,
        .tick = {.callback = tick, .user = tick_user},
    };

    ca_apply(curl);

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);
    curl_easy_setopt(curl, CURLOPT_USERAGENT, HTTP_USER_AGENT);
    if (header_list)
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, header_list);
    if (body) {
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, body);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)body_len);
    }
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, receive_buffered_data);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &state);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 2L);
    if (timeout_s > 0)
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, timeout_s);
    if (tick) {
        curl_easy_setopt(curl, CURLOPT_NOPROGRESS, 0L);
        curl_easy_setopt(curl, CURLOPT_XFERINFOFUNCTION, poll_buffered_transfer);
        curl_easy_setopt(curl, CURLOPT_XFERINFODATA, &state);
    } else {
        curl_easy_setopt(curl, CURLOPT_NOPROGRESS, 1L);
    }

    const char **trace_headers = body ? copy_headers_with(headers, content_type) : NULL;
    trace_request(body ? "POST" : "GET", url, body ? trace_headers : headers, body, body_len);
    free(trace_headers);

    CURLcode result = curl_easy_perform(curl);
    long status = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &status);
    if (status_out)
        *status_out = status;

    curl_slist_free_all(header_list);
    curl_easy_cleanup(curl);

    int failed = result != CURLE_OK || status < 200 || status >= 300 || !state.body.data;
    char *error_body = NULL;
    if (failed) {
        /* Buffered callers only see -1; surface the certificate advice out of band. */
        ca_warn_verify_failure(result);
        if (result != CURLE_OK)
            error_body = curl_error_body(result);
        else if (state.body.data)
            error_body = xstrdup(state.body.data);
    }
    trace_response_status(status, error_body);
    free(error_body);

    if (failed) {
        buf_free(&state.body);
        return -1;
    }
    *out = buf_steal(&state.body);
    return 0;
}

int http_get(const char *url, const char *const *headers, long timeout_s, long max_bytes,
             http_tick_cb tick, void *tick_user, char **out, long *status_out)
{
    return buffered_request(url, headers, NULL, 0, timeout_s, max_bytes, tick, tick_user, out,
                            status_out);
}

int http_post_json(const char *url, const char *const *headers, const char *body, size_t body_len,
                   long timeout_s, long max_bytes, http_tick_cb tick, void *tick_user, char **out)
{
    return buffered_request(url, headers, body ? body : "", body ? body_len : 0, timeout_s,
                            max_bytes, tick, tick_user, out, NULL);
}

/* SPDX-License-Identifier: MIT */
#ifndef HAX_TRANSPORT_CA_H
#define HAX_TRANSPORT_CA_H

#include <curl/curl.h>

/* Runtime discovery of the system TLS root certificate store, for binaries running on a
 * different distribution than libcurl's build baked its store path for (static or relocated
 * builds). */

/* Resolve the store once, from the main thread, after curl_global_init() and before the first
 * request. Honors the standard CURL_CA_BUNDLE / SSL_CERT_FILE / SSL_CERT_DIR variables, which
 * libcurl itself does not read. Without this call, ca_apply() and ca_verify_hint() are no-ops. */
void ca_init(void);

/* Point `curl` at the resolved store: environment overrides govern origin verification only,
 * while HTTPS proxies always verify against the probed system store. A no-op when libcurl's
 * own default is in effect. */
void ca_apply(CURL *curl);

/* Advice to append to `code`'s error message when it can stem from the missing store, or NULL
 * when the store is not the problem. */
const char *ca_verify_hint(CURLcode code);

/* Emit ca_verify_hint()'s advice through hax_warn(), once per process; for transports whose
 * error bodies never reach the user. */
void ca_warn_verify_failure(CURLcode code);

enum ca_store_source {
    CA_STORE_MISSING = -1, /* nothing found anywhere */
    CA_STORE_DEFAULT,      /* libcurl's own default or native OS trust; nothing to set */
    CA_STORE_ENV,          /* *file / *dir from environment overrides */
    CA_STORE_PROBED,       /* *file / *dir probed from the filesystem */
};

/* Resolution core, exposed for tests. `root` prefixes every probed path ("" probes the real
 * filesystem); environment values pass through unprobed. `ssl_version` and the NULL-terminated
 * `features` describe the running libcurl. `*file` / `*dir` receive malloc'd CURLOPT_CAINFO /
 * CURLOPT_CAPATH values, or NULL to leave the option alone. */
enum ca_store_source ca_resolve(const char *root, const char *env_bundle, const char *env_file,
                                const char *env_dir, const char *ssl_version,
                                const char *const *features, const char *curl_file,
                                const char *curl_dir, char **file, char **dir);

#endif /* HAX_TRANSPORT_CA_H */

/* SPDX-License-Identifier: MIT */
#ifndef HAX_TRANSPORT_HTTP_H
#define HAX_TRANSPORT_HTTP_H

#include <stddef.h>

#include "transport/sse.h"

struct http_response {
    long status;
    char *error_body;    /* heap-owned; NULL on success or cancellation */
    long retry_after_ms; /* 0 when Retry-After is absent or invalid */
    int cancelled;
};

/* Called during transfer progress and after each received chunk. Returning non-zero aborts. */
typedef int (*http_tick_cb)(void *user);

/* `headers` is a NULL-terminated array and may be NULL. `idle_timeout_s == 0` disables the
 * low-speed timeout. The response is initialized on every call; the caller owns `error_body`.
 * Returns 0 when the transfer completes, including non-2xx responses, and -1 otherwise. */
int http_sse_post(const char *url, const char *const *headers, const char *body, size_t body_len,
                  long idle_timeout_s, sse_cb cb, void *user, http_tick_cb tick, void *tick_user,
                  struct http_response *response);

/* Synchronous GET into a heap-owned NUL-terminated buffer. `headers` is a NULL-terminated array and
 * may be NULL. Returns 0 on a non-empty 2xx response; otherwise returns -1 and sets `*out` to NULL.
 * `timeout_s == 0` and `max_bytes == 0` disable their respective limits. `status_out`, when
 * non-NULL, receives 0 if no HTTP response was received. */
int http_get(const char *url, const char *const *headers, long timeout_s, long max_bytes,
             http_tick_cb tick, void *tick_user, char **out, long *status_out);

/* Synchronous JSON POST with the same response, timeout, and size contracts as http_get.
 * Content-Type is added automatically. A NULL body sends an empty POST. */
int http_post_json(const char *url, const char *const *headers, const char *body, size_t body_len,
                   long timeout_s, long max_bytes, http_tick_cb tick, void *tick_user, char **out);

#endif /* HAX_TRANSPORT_HTTP_H */

